package com.killsleft;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import javax.swing.event.ChangeEvent;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class KillsLeftPanel extends PluginPanel
{
	private final JPanel rows = new JPanel(new GridLayout(0, 1, 0, 6));
	private final JLabel hint = new JLabel("Kill monsters to begin tracking.", SwingConstants.CENTER);
	private final JButton resetAll = new JButton("Reset All");

	public KillsLeftPanel()
	{
		setLayout(new BorderLayout(0, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Kills Left", SwingConstants.CENTER);
		add(title, BorderLayout.NORTH);

		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(rows, BorderLayout.CENTER);
		add(resetAll, BorderLayout.SOUTH);
	}

	void rebuild(List<KillsLeftPlugin.Snapshot> snaps, Map<Skill, Integer> targets,
		SkillIconManager icons, java.util.function.BiConsumer<Skill, Integer> onTargetChanged,
		java.util.function.Consumer<Skill> onResetSkill, Runnable onResetAll)
	{
		rows.removeAll();

		if (snaps.isEmpty())
		{
			rows.add(hint);
		}

		for (KillsLeftPlugin.Snapshot s : snaps)
		{
			Skill skill = skillByName(s.skillName);
			if (skill == null)
			{
				continue;
			}
			rows.add(row(s, targets.getOrDefault(skill, s.level + 1), icons, onTargetChanged, onResetSkill));
		}

		for (java.awt.event.ActionListener al : resetAll.getActionListeners())
		{
			resetAll.removeActionListener(al);
		}
		resetAll.addActionListener(e -> onResetAll.run());
		resetAll.setEnabled(!snaps.isEmpty());

		revalidate();
		repaint();
	}

	private JPanel row(KillsLeftPlugin.Snapshot s, int target, SkillIconManager icons,
		java.util.function.BiConsumer<Skill, Integer> onTargetChanged,
		java.util.function.Consumer<Skill> onResetSkill)
	{
		Skill skill = skillByName(s.skillName);
		JPanel p = new JPanel(new BorderLayout(6, 4));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(6, 6, 6, 6));

		BufferedImage img = null;
		try
		{
			img = icons.getSkillImage(skill);
		}
		catch (Exception ignored)
		{
		}
		JLabel icon = img == null ? new JLabel() : new JLabel(new ImageIcon(img));
		p.add(icon, BorderLayout.WEST);

		JPanel mid = new JPanel(new GridLayout(0, 1));
		mid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		String kills = s.killsLeft < 0 ? "done" : s.killsLeft + " kills";
		mid.add(new JLabel(s.skillName + " " + s.level + " → " + s.target));
		mid.add(new JLabel(kills + "  (" + (int) Math.round(s.progress * 100) + "%)"));
		JButton reset = new JButton("Reset");
		reset.addActionListener(e -> onResetSkill.accept(skill));
		mid.add(reset);
		p.add(mid, BorderLayout.CENTER);

		JSpinner spinner = new JSpinner(new SpinnerNumberModel(
			Math.min(99, Math.max(s.level + 1, target)), s.level + 1, 99, 1));
		spinner.addChangeListener((ChangeEvent e) ->
			onTargetChanged.accept(skill, (Integer) spinner.getValue()));
		p.add(spinner, BorderLayout.EAST);

		return p;
	}

	private Skill skillByName(String name)
	{
		for (Skill s : Skill.values())
		{
			if (s.getName().equals(name))
			{
				return s;
			}
		}
		return null;
	}
}

package com.killsleft;

import com.google.inject.Provides;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.game.SkillIconManager;

@Slf4j
@PluginDescriptor(
	name = "Kills Left",
	description = "Kills left to level from average XP per kill, auto-tracking combat skills gaining XP",
	tags = {"xp", "tracker", "combat", "kills"}
)
public class KillsLeftPlugin extends Plugin
{
	private static final Skill[] COMBAT_SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE,
		Skill.RANGED, Skill.MAGIC, Skill.HITPOINTS, Skill.SLAYER
	};

	@Inject
	private Client client;

	@Inject
	private KillsLeftConfig config;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	private NavigationButton navButton;
	private KillsLeftPanel panel;

	private final Map<Skill, Integer> skillTargets = new EnumMap<>(Skill.class);

	private final Map<Skill, KillsLeftInfoBox> infoBoxes = new EnumMap<>(Skill.class);

	// Per-skill rolling XP-per-kill history
	private final Map<Skill, Deque<Double>> recentKillXp = new EnumMap<>(Skill.class);
	// XP at fight start (set on interact), so 1 kill is enough after XP drops arrive
	private final Map<Skill, Integer> fightStartXp = new EnumMap<>(Skill.class);
	private int killsSeen = 0;
	private int pendingXPTicks = 0;

	// Interacting is usually cleared by the time ActorDeath fires, so remember last target.
	private NPC lastTarget;
	private long lastTargetTimeMs;

	@Override
	protected void startUp() throws Exception
	{
		fightStartXp.clear();
		recentKillXp.clear();
		pendingXPTicks = 0;
		loadTargets();

		panel = new KillsLeftPanel();
		java.awt.image.BufferedImage icon = net.runelite.client.util.ImageUtil.loadImageResource(getClass(), "/killsleft_icon.png");
		if (icon == null)
		{
			try
			{
				icon = skillIconManager.getSkillImage(Skill.ATTACK);
			}
			catch (Exception e)
			{
				icon = new java.awt.image.BufferedImage(16, 16, java.awt.image.BufferedImage.TYPE_INT_ARGB);
			}
		}
		navButton = NavigationButton.builder()
			.tooltip("Kills Left")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		refreshPanel();
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		for (KillsLeftInfoBox box : infoBoxes.values())
		{
			infoBoxManager.removeInfoBox(box);
		}
		infoBoxes.clear();
		recentKillXp.clear();
		fightStartXp.clear();
		killsSeen = 0;
		pendingXPTicks = 0;
	}

	@Provides
	KillsLeftConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(KillsLeftConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!e.getGroup().equals("killsleft"))
		{
			return;
		}
		if (e.getKey().equals("showInfoBoxes") && !config.showInfoBoxes())
		{
			for (KillsLeftInfoBox box : infoBoxes.values())
			{
				infoBoxManager.removeInfoBox(box);
			}
			infoBoxes.clear();
		}
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged e)
	{
		if (e.getSource() == client.getLocalPlayer() && e.getTarget() instanceof NPC)
		{
			lastTarget = (NPC) e.getTarget();
			lastTargetTimeMs = System.currentTimeMillis();
			for (Skill skill : trackedSkills())
			{
				try
				{
					fightStartXp.put(skill, client.getSkillExperience(skill));
				}
				catch (Exception ignored)
				{
				}
			}
			pendingXPTicks = 0;
		}
	}

	@Subscribe
	public void onGameTick(net.runelite.api.events.GameTick t)
	{
		if (pendingXPTicks > 0 && --pendingXPTicks == 0)
		{
			resolvePendingKill();
		}
		else
		{
			refreshPanel();
		}
	}

	private void resolvePendingKill()
	{
		for (Skill skill : trackedSkills())
		{
			Integer start = fightStartXp.get(skill);
			if (start == null)
			{
				continue;
			}
			int currentXp;
			try
			{
				currentXp = client.getSkillExperience(skill);
			}
			catch (Exception ex)
			{
				continue;
			}
			int delta = currentXp - start;
			if (delta >= 1 && delta < 200_000)
			{
				pushKillXp(skill, delta);
			}
			fightStartXp.put(skill, currentXp);
		}
		syncInfoBoxes();
		refreshPanel();
	}

	private void syncInfoBoxes()
	{
		if (!config.showInfoBoxes())
		{
			for (KillsLeftInfoBox box : infoBoxes.values())
			{
				infoBoxManager.removeInfoBox(box);
			}
			infoBoxes.clear();
			return;
		}
		for (Snapshot s : snapshots())
		{
			Skill skill = skillByName(s.skillName);
			if (skill == null)
			{
				continue;
			}
			KillsLeftInfoBox box = infoBoxes.get(skill);
			if (box == null)
			{
				try
				{
					box = new KillsLeftInfoBox(skillIconManager.getSkillImage(skill), this, s.skillName);
					// Add to end so ours sit under existing RuneLite infoboxes
					infoBoxManager.addInfoBox(box);
					infoBoxes.put(skill, box);
				}
				catch (Exception e)
				{
					log.debug("infobox create failed for {}", skill, e);
					continue;
				}
			}
			box.update(s.killsLeft, s.avgXpPerKill, s.level, s.target, s.samples, s.progress);
		}
	}

	private Skill skillByName(String name)
	{
		for (Skill s : COMBAT_SKILLS)
		{
			if (s.getName().equals(name))
			{
				return s;
			}
		}
		return null;
	}

	@Subscribe
	public void onActorDeath(ActorDeath death)
	{
		Actor actor = death.getActor();
		if (!(actor instanceof NPC))
		{
			return;
		}
		if (!wasMyKill((NPC) actor))
		{
			return;
		}
		killsSeen++;
		pendingXPTicks = 2;
	}

	private boolean wasMyKill(NPC npc)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return false;
		}
		if (me.getInteracting() == npc || npc.getInteracting() == me)
		{
			return true;
		}
		return npc == lastTarget && System.currentTimeMillis() - lastTargetTimeMs < 15_000;
	}

	private List<Skill> trackedSkills()
	{
		List<Skill> out = new ArrayList<>(7);
		for (Skill s : COMBAT_SKILLS)
		{
			if (s == Skill.SLAYER && !config.showSlayer())
			{
				continue;
			}
			out.add(s);
		}
		return out;
	}

	private void pushKillXp(Skill skill, double xp)
	{
		int window = Math.max(1, Math.min(100, config.avgKills()));
		Deque<Double> q = recentKillXp.computeIfAbsent(skill, k -> new ArrayDeque<>());
		q.addLast(xp);
		while (q.size() > window)
		{
			q.pollFirst();
		}
	}

	List<Snapshot> snapshots()
	{
		List<Snapshot> out = new ArrayList<>();
		for (Skill skill : trackedSkills())
		{
			Deque<Double> q = recentKillXp.get(skill);
			if (q == null || q.isEmpty())
			{
				continue;
			}
			double avg = 0;
			for (double d : q)
			{
				avg += d;
			}
			avg /= q.size();

			int xp;
			try
			{
				xp = client.getSkillExperience(skill);
			}
			catch (Exception e)
			{
				continue;
			}

			int level = Experience.getLevelForXp(xp);
			int target = getSkillTarget(skill, level);
			long killsLeft;
			double progress;
			if (level >= target)
			{
				killsLeft = -1;
				progress = 1.0;
			}
			else
			{
				int curLevelXp = Experience.getXpForLevel(level);
				int targetXp = Experience.getXpForLevel(target);
				int remaining = Math.max(0, targetXp - xp);
				killsLeft = avg > 0 ? (long) Math.ceil(remaining / avg) : 0;
				progress = targetXp > curLevelXp
					? (double) (xp - curLevelXp) / (targetXp - curLevelXp)
					: 0.0;
			}
			out.add(new Snapshot(skill.getName(), level, target, avg, killsLeft, q.size(), progress));
		}
		return out;
	}

	int getKillsSeen()
	{
		return killsSeen;
	}

	private int getSkillTarget(Skill skill, int level)
	{
		Integer t = skillTargets.get(skill);
		if (t == null)
		{
			return Math.min(99, level + 1);
		}
		return Math.min(99, Math.max(level + 1, t));
	}

	private void loadTargets()
	{
		skillTargets.clear();
		for (Skill s : COMBAT_SKILLS)
		{
			try
			{
				String v = configManager.getConfiguration("killsleft", "target_" + s.name());
				if (v != null)
				{
					skillTargets.put(s, Math.min(99, Math.max(2, Integer.parseInt(v))));
				}
			}
			catch (Exception ignored)
			{
			}
		}
	}

	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		List<Snapshot> snaps = snapshots();
		// Default each newly-seen skill to next level until user changes it
		for (Snapshot s : snaps)
		{
			Skill skill = skillByName(s.skillName);
			if (skill != null && !skillTargets.containsKey(skill))
			{
				skillTargets.put(skill, Math.min(99, s.level + 1));
			}
		}
		javax.swing.SwingUtilities.invokeLater(() ->
			panel.rebuild(snaps, skillTargets, skillIconManager, (skill, target) ->
			{
				skillTargets.put(skill, Math.min(99, Math.max(2, target)));
				configManager.setConfiguration("killsleft", "target_" + skill.name(), String.valueOf(target));
				syncInfoBoxes();
				refreshPanel();
			},
			skill ->
			{
				resetSkill(skill);
			},
			() ->
			{
				resetAll();
			}));
	}

	private void resetSkill(Skill skill)
	{
		recentKillXp.remove(skill);
		fightStartXp.remove(skill);
		KillsLeftInfoBox box = infoBoxes.remove(skill);
		if (box != null)
		{
			infoBoxManager.removeInfoBox(box);
		}
		refreshPanel();
	}

	private void resetAll()
	{
		recentKillXp.clear();
		fightStartXp.clear();
		for (KillsLeftInfoBox box : infoBoxes.values())
		{
			infoBoxManager.removeInfoBox(box);
		}
		infoBoxes.clear();
		killsSeen = 0;
		pendingXPTicks = 0;
		refreshPanel();
	}

	static class Snapshot
	{
		final String skillName;
		final int level;
		final int target;
		final double avgXpPerKill;
		final long killsLeft;
		final int samples;
		final double progress;

		Snapshot(String skillName, int level, int target, double avgXpPerKill, long killsLeft, int samples, double progress)
		{
			this.skillName = skillName;
			this.level = level;
			this.target = target;
			this.avgXpPerKill = avgXpPerKill;
			this.killsLeft = killsLeft;
			this.samples = samples;
			this.progress = progress;
		}
	}
}

package com.killsleft;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("killsleft")
public interface KillsLeftConfig extends Config
{
	@ConfigItem(
		keyName = "showInfoBoxes",
		name = "Show infoboxes",
		description = "Show per-skill infoboxes with kills left."
	)
	default boolean showInfoBoxes()
	{
		return true;
	}

	@ConfigItem(
		keyName = "avgKills",
		name = "Kills to average",
		description = "Rolling average over this many recent kills. Higher = smoother."
	)
	default int avgKills()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "showSlayer",
		name = "Show Slayer",
		description = "Include Slayer when gaining Slayer XP."
	)
	default boolean showSlayer()
	{
		return true;
	}
}

package com.killsleft;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

public class KillsLeftInfoBox extends InfoBox
{
	private static final Color ALMOST = new Color(0x66, 0xBB, 0x6A); // green
	private static final Color SOON = new Color(0xFF, 0xCA, 0x28); // amber
	private static final Color GRIND = Color.WHITE;

	private final String skillName;
	private volatile String text = "?";
	private volatile Color textColor = GRIND;
	private volatile String tooltip = "Kills left";

	public KillsLeftInfoBox(BufferedImage image, Plugin plugin, String skillName)
	{
		super(image, plugin);
		this.skillName = skillName;
	}

	public void update(long killsLeft, double avgXp, int level, int target, int samples, double progress)
	{
		if (killsLeft < 0)
		{
			this.text = "done";
			this.textColor = GRIND;
		}
		else
		{
			this.text = compact(killsLeft);
			this.textColor = killsLeft <= 25 ? ALMOST : killsLeft <= 150 ? SOON : GRIND;
		}
		double p = Math.min(1.0, Math.max(0.0, progress));
		int pct = (int) Math.round(p * 100);
		this.tooltip = skillName + " " + level + " to " + target
			+ "<br>" + pct + "% to " + target
			+ "<br>Avg " + (long) avgXp + " XP/kill"
			+ "<br>" + (killsLeft < 0 ? "done" : Long.toString(killsLeft)) + " kills left";
	}

	@Override
	public String getText()
	{
		return text;
	}

	@Override
	public Color getTextColor()
	{
		return textColor;
	}

	@Override
	public String getTooltip()
	{
		return tooltip;
	}

	private static String compact(long n)
	{
		if (n >= 1_000_000)
		{
			return trim1(n / 1_000_000.0) + "M";
		}
		if (n >= 1000)
		{
			return trim1(n / 1000.0) + "K";
		}
		return Long.toString(n);
	}

	private static String trim1(double v)
	{
		String s = String.format(java.util.Locale.US, "%.1f", v);
		if (s.endsWith(".0"))
		{
			s = s.substring(0, s.length() - 2);
		}
		return s;
	}
}
